# -*- coding: utf-8 -*-
"""
Cotizador visual: selector de COLOR de la unidad.

El administrador sube la misma unidad en cada color (misma toma que la foto
principal) con su nombre y muestra de color. Al cotizar aparece una fila
deslizable de colores; al elegir uno cambia la foto de la unidad (los
accesorios se quedan en su lugar), la imagen descargable y la del PDF, y el
color se anota en el nombre del articulo principal de la cotizacion.

Requiere que fix_cotizador_visual.py ya este aplicado.
Toca: frontend/index.html, backend/app.py. Se puede correr varias veces.

Uso: en la carpeta del repo:
    py -3 fix_cotizador_visual_colores.py
"""
import os
import sys

ARCHIVOS = {'frontend/index.html': [['    .cv-chip { display:inline-block;', '    .cv-layout > * { min-width:0; }\n    .cv-colores { max-width:100%; display:flex; gap:8px; overflow-x:auto; padding:4px 2px 8px; margin-top:10px; scroll-snap-type:x proximity; -webkit-overflow-scrolling:touch; }\n    .cv-color { flex:none; width:96px; scroll-snap-align:start; display:flex; flex-direction:column; gap:4px; padding:4px; border:1px solid rgba(155,157,159,0.35); border-radius:8px; background:var(--panel); cursor:pointer; color:inherit; text-transform:none; letter-spacing:0; font-weight:400; box-shadow:none; }\n    .cv-color.on { border-color:var(--copper); box-shadow:inset 0 0 0 1px var(--copper); }\n    .cv-color-img { display:flex; align-items:center; justify-content:center; height:62px; background:#fff; border-radius:5px; overflow:hidden; }\n    .cv-color-img img { max-width:100%; max-height:100%; object-fit:contain; }\n    .cv-color-nom { display:flex; gap:5px; align-items:center; justify-content:center; font-size:11px; line-height:1.2; text-align:center; }\n    .cv-color-nom i { width:10px; height:10px; border-radius:50%; flex:none; border:1px solid rgba(155,157,159,0.6); }\n    .cv-chip { display:inline-block;'], ['let CV_DESHACER = {};\n', "let CV_DESHACER = {};\nlet CV_EDIT_COLOR = '__base'; // color que se está viendo en el editor\n"], ["  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, cliente: { nombre: '', telefono: '', tipo: 'publico' } };\n", "  cfg.colores = cfg.colores || [];\n  CV_SEL = { activos: [], desc: {}, precio: {}, fuente: {}, color: CV_BASE, cliente: { nombre: '', telefono: '', tipo: 'publico' } };\n"], ['        <div class="cv-stage" id="cv_stage">${cv_htmlStage(cfg, CV_SEL.activos, false)}</div>\n', '        <div class="cv-stage" id="cv_stage">${cv_htmlStage(cv_cfgConColor(cfg, CV_SEL.color), CV_SEL.activos, false)}</div>\n        ${cv_listaColores(cfg).length ? `<span class="cv-etq" style="margin-bottom:0;">Color de la unidad: <b style="color:var(--text);">${escapeHtml((cv_colorPorUid(cfg, CV_SEL.color) || {}).nombre || \'\')}</b></span>` : \'\'}\n        ${cv_htmlSelectorColores(cfg, CV_SEL.color, \'cv_setColor\')}\n'], ["function cv_bandaPrecio() {\n  return { izq: `${CV_KIT.nombre} · IVA incluido`, der: '$' + cot_fmt(cv_totales().total) };\n}\n", "function cv_nombreColorSel() {\n  const c = CV_KIT && cv_colorPorUid(CV_KIT.config, CV_SEL.color);\n  return c ? c.nombre : '';\n}\n\nfunction cv_bandaPrecio() {\n  const color = cv_nombreColorSel();\n  return { izq: `${CV_KIT.nombre}${color ? ' · ' + color : ''} · IVA incluido`, der: '$' + cot_fmt(cv_totales().total) };\n}\n"], ['  const canvas = await cv_componerImagen(CV_KIT.config, CV_SEL.activos, conPrecio && conPrecio.checked ? cv_bandaPrecio() : null);\n', '  const canvas = await cv_componerImagen(cv_cfgConColor(CV_KIT.config, CV_SEL.color), CV_SEL.activos, conPrecio && conPrecio.checked ? cv_bandaPrecio() : null);\n'], ['      const canvas = await cv_componerImagen(CV_KIT.config, CV_SEL.activos, null);\n', '      const canvas = await cv_componerImagen(cv_cfgConColor(CV_KIT.config, CV_SEL.color), CV_SEL.activos, null);\n      const color = cv_nombreColorSel();\n'], ['          articulo_id: l.p.articulo_id || null, clave: l.p.clave || null, nombre: l.p.nombre,\n', '          articulo_id: l.p.articulo_id || null, clave: l.p.clave || null,\n          nombre: (l.uid === CV_BASE && color) ? `${l.p.nombre} — COLOR: ${color.toUpperCase()}` : l.p.nombre,\n'], ['        config_visual: { kit_id: CV_KIT.id, kit_nombre: CV_KIT.nombre, activos: CV_SEL.activos, descuentos: CV_SEL.desc },\n', '        config_visual: { kit_id: CV_KIT.id, kit_nombre: CV_KIT.nombre, activos: CV_SEL.activos, descuentos: CV_SEL.desc, color: CV_SEL.color, color_nombre: color || null },\n'], ['\n// ---------- Editor de equipos (solo administrador) ----------', '\n// ---------- Colores de la unidad ----------\n// config.colores = [{ uid, nombre, hex, imagen }] — la MISMA unidad en otro\n// color, con la misma toma/encuadre que la foto principal (así los\n// accesorios caen en el mismo lugar). La foto principal cuenta como el\n// primer color (config.base.color_nombre / color_hex).\n\nfunction cv_listaColores(cfg) {\n  const extra = (cfg.colores || []).filter(c => c.imagen);\n  if (!extra.length) return [];\n  return [\n    { uid: CV_BASE, nombre: (cfg.base.color_nombre || \'\').trim() || \'Color original\', hex: cfg.base.color_hex || \'\', imagen: cfg.base.imagen },\n    ...extra.map(c => ({ ...c, nombre: (c.nombre || \'\').trim() || \'Sin nombre\' })),\n  ];\n}\n\nfunction cv_colorPorUid(cfg, uid) {\n  return cv_listaColores(cfg).find(c => c.uid === uid) || null;\n}\n\n// Copia del config con la foto principal cambiada por la del color elegido.\nfunction cv_cfgConColor(cfg, uid) {\n  if (!uid || uid === CV_BASE) return cfg;\n  const c = (cfg.colores || []).find(x => x.uid === uid && x.imagen);\n  return c ? { ...cfg, base: { ...cfg.base, imagen: c.imagen } } : cfg;\n}\n\nfunction cv_htmlSelectorColores(cfg, uidSel, funcion) {\n  const lista = cv_listaColores(cfg);\n  if (!lista.length) return \'\';\n  return `\n    <div class="cv-colores">\n      ${lista.map(c => `\n        <button type="button" class="cv-color${c.uid === uidSel ? \' on\' : \'\'}" onclick="${funcion}(\'${c.uid}\')" title="${escapeHtml(c.nombre)}">\n          <span class="cv-color-img"><img src="${c.imagen}" alt="" /></span>\n          <span class="cv-color-nom">${c.hex ? `<i style="background:${escapeHtml(c.hex)};"></i>` : \'\'}${escapeHtml(c.nombre)}</span>\n        </button>`).join(\'\')}\n    </div>`;\n}\n\nfunction cv_setColor(uid) {\n  CV_SEL.color = uid;\n  cv_renderCotizar();\n}\n\nfunction cv_setColorEditor(uid) {\n  CV_EDIT_COLOR = uid;\n  cv_renderEditor();\n}\n\nasync function cv_proporcion(dataUrl) {\n  const img = await cv_cargarImagen(dataUrl);\n  return img.naturalWidth / img.naturalHeight;\n}\n\n// Sube (uid null = color nuevo) o reemplaza la foto de un color.\nfunction cv_elegirFotoColor(uid) {\n  const inp = document.createElement(\'input\');\n  inp.type = \'file\';\n  inp.accept = \'image/*\';\n  inp.onchange = async () => {\n    const f = inp.files && inp.files[0];\n    if (!f) return;\n    try {\n      const c = CV_EDIT.config;\n      const imagen = await cv_leerArchivoImagen(f, 1600, true);\n      let color = uid ? c.colores.find(x => x.uid === uid) : null;\n      if (!color) {\n        color = { uid: cv_uid(), nombre: \'\', hex: \'#cccccc\', imagen: null };\n        c.colores.push(color);\n      }\n      color.imagen = imagen;\n      color.aviso = false;\n      if (c.base.imagen) {\n        const [pb, pc] = await Promise.all([cv_proporcion(c.base.imagen), cv_proporcion(imagen)]);\n        color.aviso = Math.abs(pb - pc) / pb > 0.03;\n      }\n      CV_EDIT_COLOR = color.uid;\n      cv_renderEditor();\n      const el = document.getElementById(`cv_color_nom_${color.uid}`);\n      if (el && !color.nombre) el.focus();\n    } catch (e) { alert(e.message); }\n  };\n  inp.click();\n}\n\nfunction cv_setColorCampo(uid, campo, valor) {\n  const c = (CV_EDIT.config.colores || []).find(x => x.uid === uid);\n  if (c) c[campo] = valor;\n}\n\nfunction cv_quitarColor(uid) {\n  const c = (CV_EDIT.config.colores || []).find(x => x.uid === uid);\n  if (!confirm(`¿Quitar el color "${(c && c.nombre) || \'sin nombre\'}"?`)) return;\n  CV_EDIT.config.colores = CV_EDIT.config.colores.filter(x => x.uid !== uid);\n  if (CV_EDIT_COLOR === uid) CV_EDIT_COLOR = CV_BASE;\n  cv_renderEditor();\n}\n\nfunction cv_htmlEditorColores() {\n  const c = CV_EDIT.config;\n  return `\n    <span class="cv-etq">Colores de la unidad (opcional)</span>\n    <div class="cv-caja">\n      <p style="font-size:12px; color:var(--muted); margin:0 0 10px;">Sube la MISMA unidad en cada color, tomada igual que la foto principal (mismo ángulo, tamaño y encuadre) para que los accesorios caigan en el mismo lugar. El vendedor elige el color deslizando la fila de colores.</p>\n      <div class="row-2">\n        <div class="field"><label>Color de la foto principal</label>\n          <div style="display:flex; gap:6px; align-items:center;">\n            <input type="color" value="${escapeHtml(c.base.color_hex || \'#cccccc\')}" style="width:46px; height:38px; padding:2px; flex:none;" oninput="CV_EDIT.config.base.color_hex=this.value" />\n            <input value="${escapeHtml(c.base.color_nombre || \'\')}" placeholder="ej. Azul cielo" style="flex:1;" oninput="CV_EDIT.config.base.color_nombre=this.value" />\n          </div>\n        </div>\n        <div></div>\n      </div>\n      ${c.colores.map(col => `\n        <div style="display:flex; gap:10px; align-items:center; flex-wrap:wrap; padding:8px 0; border-top:1px solid rgba(155,157,159,0.2);">\n          <div class="cv-thumb">${col.imagen ? `<img src="${col.imagen}" alt="" />` : \'🎨\'}</div>\n          <input type="color" value="${escapeHtml(col.hex || \'#cccccc\')}" style="width:46px; height:38px; padding:2px; flex:none;" oninput="cv_setColorCampo(\'${col.uid}\',\'hex\',this.value)" />\n          <input id="cv_color_nom_${col.uid}" value="${escapeHtml(col.nombre || \'\')}" placeholder="Nombre del color *" style="flex:1; min-width:140px;" oninput="cv_setColorCampo(\'${col.uid}\',\'nombre\',this.value)" />\n          <button type="button" class="secondary" onclick="cv_elegirFotoColor(\'${col.uid}\')">📷 Cambiar foto</button>\n          <button type="button" class="secondary" style="color:var(--copper); border-color:var(--copper);" onclick="cv_quitarColor(\'${col.uid}\')">✕</button>\n          ${col.aviso ? `<div style="flex-basis:100%; font-size:11px; color:var(--alta);">⚠️ Esta foto no tiene la misma proporción que la foto principal — revisa en el paso 2 que los accesorios sigan cayendo en su lugar.</div>` : \'\'}\n        </div>`).join(\'\')}\n      <button type="button" class="secondary" style="margin-top:8px;" ${c.base.imagen ? \'\' : \'disabled title="Primero sube la foto principal"\'} onclick="cv_elegirFotoColor(null)">🎨 + Agregar color</button>\n    </div>`;\n}\n\n// ---------- Editor de equipos (solo administrador) ----------'], ['  CV_EDIT_SEL = null; CV_BUSQ = {}; CV_DESHACER = {};\n', '  CV_EDIT_SEL = null; CV_BUSQ = {}; CV_DESHACER = {}; CV_EDIT_COLOR = CV_BASE;\n'], ["    CV_EDIT = { id: null, nombre: '', activo: true, config: { base: cv_productoVacio(), accesorios: [], combos: [] } };\n", "    CV_EDIT = { id: null, nombre: '', activo: true, config: { base: cv_productoVacio(), accesorios: [], combos: [], colores: [] } };\n"], ["  c.combos = (c.combos || []).map(cb => ({ nombre: '', descuento_pct: 0, incluye_base: true, requiere: [], ...cb }));\n  cv_renderEditor();\n", "  c.combos = (c.combos || []).map(cb => ({ nombre: '', descuento_pct: 0, incluye_base: true, requiere: [], ...cb }));\n  c.colores = (c.colores || []).map(col => ({ uid: cv_uid(), nombre: '', hex: '#cccccc', imagen: null, ...col }));\n  cv_renderEditor();\n"], ['      <button type="button" class="secondary" onclick="cv_elegirFoto(\'${CV_BASE}\')">📷 ${c.base.imagen ? \'Cambiar foto principal\' : \'Subir foto principal *\'}</button>\n    </div>\n\n    <span class="cv-etq">2 · Acomoda los accesorios sobre la foto</span>\n    <div class="cv-layout">\n      <div class="cv-stage editando" id="cv_stage_edit">${cv_htmlStage(c, todos, true)}</div>\n', '      <button type="button" class="secondary" onclick="cv_elegirFoto(\'${CV_BASE}\')">📷 ${c.base.imagen ? \'Cambiar foto principal\' : \'Subir foto principal *\'}</button>\n    </div>\n    ${cv_htmlEditorColores()}\n\n    <span class="cv-etq">2 · Acomoda los accesorios sobre la foto</span>\n    <div class="cv-layout">\n      <div>\n        <div class="cv-stage editando" id="cv_stage_edit">${cv_htmlStage(cv_cfgConColor(c, CV_EDIT_COLOR), todos, true)}</div>\n        ${cv_listaColores(c).length ? \'<div style="font-size:11px; color:var(--muted); margin-top:8px;">Vista previa por color (la posición de los accesorios es la misma para todos):</div>\' : \'\'}\n        ${cv_htmlSelectorColores(c, CV_EDIT_COLOR, \'cv_setColorEditor\')}\n      </div>\n'], ["  if (sinNombre) { alert('Hay un accesorio sin nombre — escríbele nombre o quítalo.'); return; }\n", '  if (sinNombre) { alert(\'Hay un accesorio sin nombre — escríbele nombre o quítalo.\'); return; }\n  if ((c.colores || []).some(col => !col.imagen)) { alert(\'Hay un color sin foto — súbele foto o quítalo.\'); return; }\n  if ((c.colores || []).some(col => !(col.nombre || \'\').trim())) { alert(\'Hay un color sin nombre — escríbele nombre (ej. Azul cielo).\'); return; }\n  if ((c.colores || []).length && !(c.base.color_nombre || \'\').trim()) { alert(\'Escribe también el nombre del color de la foto principal (en "Colores de la unidad").\'); return; }\n']], 'backend/app.py': [['    if not isinstance(config.get("accesorios", []), list) or not isinstance(config.get("combos", []), list):', '    if not isinstance(config.get("accesorios", []), list) or not isinstance(config.get("combos", []), list) \\\n            or not isinstance(config.get("colores", []), list):']]}

def main():
    errores = []
    cambios = {}
    for ruta, pares in ARCHIVOS.items():
        if not os.path.exists(ruta):
            errores.append(f"No encontre {ruta} -- corre el script desde la carpeta del repo.")
            continue
        with open(ruta, encoding="utf-8", newline="") as f:
            original = f.read()
        texto = original
        for i, (viejo, nuevo) in enumerate(pares, 1):
            # En Windows git puede dejar los archivos con saltos de linea
            # CRLF (\r\n): se prueba el texto tal cual y, si no aparece,
            # la version con CRLF.
            variantes = [(viejo, nuevo)]
            if "\n" in viejo:
                variantes.append((viejo.replace("\n", "\r\n"), nuevo.replace("\n", "\r\n")))
            if any(nv in texto for _, nv in variantes):
                continue  # ya aplicado
            elegido = None
            for vj, nv in variantes:
                if texto.count(vj) == 1:
                    elegido = (vj, nv)
                    break
            if not elegido:
                n = max(texto.count(vj) for vj, _ in variantes)
                errores.append(f"{ruta}: cambio #{i} -- el texto a reemplazar aparece {n} veces (se esperaba 1).")
                continue
            texto = texto.replace(elegido[0], elegido[1], 1)
        if texto != original:
            cambios[ruta] = texto
    if errores:
        print("NO se aplico nada:")
        for e in errores:
            print("  -", e)
        sys.exit(1)
    for ruta, texto in cambios.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("Actualizado:", ruta)
    if not cambios:
        print("Todo ya estaba aplicado, no hubo cambios.")
    else:
        print("Listo.")


if __name__ == "__main__":
    main()
